local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TeleportService = game:GetService("TeleportService")
local TweenService = game:GetService("TweenService")

local LocalPlayer = Players.LocalPlayer
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

local function notify(text, duration)
    duration = duration or 3.5
    local ScreenGui = Instance.new("ScreenGui")
    ScreenGui.Name = "Notify"
    ScreenGui.ResetOnSpawn = false
    ScreenGui.Parent = PlayerGui

    local Frame = Instance.new("Frame")
    Frame.Size = UDim2.new(0, 290, 0, 48)
    Frame.Position = UDim2.new(0.5, -145, 0.12, 0)
    Frame.BackgroundColor3 = Color3.fromRGB(22, 22, 28)
    Frame.BorderSizePixel = 0
    Frame.Parent = ScreenGui

    local UICorner = Instance.new("UICorner")
    UICorner.CornerRadius = UDim.new(0, 10)
    UICorner.Parent = Frame

    local TextLabel = Instance.new("TextLabel")
    TextLabel.Size = UDim2.new(1, -16, 1, 0)
    TextLabel.Position = UDim2.new(0, 8, 0, 0)
    TextLabel.BackgroundTransparency = 1
    TextLabel.Text = text
    TextLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    TextLabel.TextSize = 14
    TextLabel.Font = Enum.Font.GothamMedium
    TextLabel.TextXAlignment = Enum.TextXAlignment.Left
    TextLabel.Parent = Frame

    Frame.BackgroundTransparency = 1
    TextLabel.TextTransparency = 1
    TweenService:Create(Frame, TweenInfo.new(0.25), {BackgroundTransparency = 0}):Play()
    TweenService:Create(TextLabel, TweenInfo.new(0.25), {TextTransparency = 0}):Play()

    task.delay(duration, function()
        TweenService:Create(Frame, TweenInfo.new(0.25), {BackgroundTransparency = 1}):Play()
        TweenService:Create(TextLabel, TweenInfo.new(0.25), {TextTransparency = 1}):Play()
        task.wait(0.3)
        ScreenGui:Destroy()
    end)
end

