local PermanentKeys = {
    "VBL-OWNER-2026",
    "DELTA-MASTER-KEY",
    "GROK-FULL-ACCESS",
    "VBL-PERM-ALPHA1",
    "VBL-PERM-BETA2",
    "VBL-PERM-GAMMA3",
    "VBL-PERM-DELTA4",
    "VBL-PERM-OMEGA5",
    "VBL-OWNER-VIP1",
    "VBL-OWNER-VIP2",
    "DELTA-FULL-2026",
    "GROK-LEGENDS-KEY",
    "VBL-MASTER-PERM",
}

local function checkKey(key)
    key = key:gsub("%s+", ""):upper()

    if KeysLifetime[key] then
        return true, "Key permanente / lifetime"
    end
    if Keys30d[key] then
        return true, "Key 30d valida"
    end
    if Keys7d[key] then
        return true, "Key 7d valida"
    end
    if Keys5d[key] then
        return true, "Key 5d valida"
    end
    if Keys1d[key] then
        return true, "Key 1d valida"
    end

    for _, pk in ipairs(PermanentKeys) do
        if key == pk then
            return true, "Key permanente valida"
        end
    end

    local year, month, day, code = key:match("^VBL%-(%d%d%d%d)(%d%d)(%d%d)%-(%w+)$")
    if year and month and day and code then
        local expireDate = tonumber(year .. month .. day)
        local today = tonumber(os.date("%Y%m%d"))
        if today <= expireDate then
            return true, "Key valida hasta " .. day .. "/" .. month .. "/" .. year
        else
            return false, "Key expirada"
        end
    end

    return false, "Key invalida"
end

local function doDataRollback()
    notify("Enviando rollback...", 2.8)

    local success = pcall(function()
        local packages = ReplicatedStorage:WaitForChild("Packages", 6)
        local index = packages:WaitForChild("_Index", 6)
        local knitPkg = index:WaitForChild("sleitnick_knit@1.7.0", 6)
        local knit = knitPkg:WaitForChild("knit", 6)
        local services = knit:WaitForChild("Services", 6)
        local settings = services:WaitForChild("SettingsService", 6)
        local rfFolder = settings:WaitForChild("RF", 6)
        local update = rfFolder:WaitForChild("UpdateKeybind", 6)

        local zwsp = utf8.char(0x200B)
        local payloads = {
            {"MouseButton1", true, "Spike" .. string.char(143)},
            {"MouseButton1", true, "Spike" .. zwsp .. string.char(143)},
            {"MouseButton1", true, "Spike" .. zwsp},
            {"MouseButton1", true, "Spike"},
            {"MouseButton1", true, "Spike" .. string.char(0)},
            {"MouseButton1", true, "Spike\0"},
        }

        for _, args in ipairs(payloads) do
            pcall(function()
                if update:IsA("RemoteFunction") then
                    update:InvokeServer(unpack(args))
                else
                    update:FireServer(unpack(args))
                end
            end)
            task.wait(0.035)
        end
    end)

    if not success then
        notify("Rollback fallo", 4)
        return
    end

    notify("Rollback enviado. Rejoining...", 2.5)
    task.wait(0.4)

    pcall(function()
        TeleportService:Teleport(game.PlaceId)
    end)
end

local function createMainUI()
    local ScreenGui = Instance.new("ScreenGui")
    ScreenGui.Name = "RollbackUI"
    ScreenGui.ResetOnSpawn = false
    ScreenGui.Parent = PlayerGui

    local Main = Instance.new("Frame")
    Main.Size = UDim2.new(0, 210, 0, 110)
    Main.Position = UDim2.new(0.5, -105, 0.35, 0)
    Main.BackgroundColor3 = Color3.fromRGB(22, 22, 28)
    Main.BorderSizePixel = 0
    Main.Active = true
    Main.Draggable = true
    Main.Parent = ScreenGui

    local UICorner = Instance.new("UICorner")
    UICorner.CornerRadius = UDim.new(0, 12)
    UICorner.Parent = Main

    local Title = Instance.new("TextLabel")
    Title.Size = UDim2.new(1, 0, 0, 32)
    Title.BackgroundTransparency = 1
    Title.Text = "AGX HUB | Rollback"
    Title.TextColor3 = Color3.fromRGB(255, 255, 255)
    Title.TextSize = 15
    Title.Font = Enum.Font.GothamBold
    Title.Parent = Main

    local Button = Instance.new("TextButton")
    Button.Size = UDim2.new(1, -24, 0, 42)
    Button.Position = UDim2.new(0, 12, 0, 48)
    Button.BackgroundColor3 = Color3.fromRGB(0, 170, 255)
    Button.Text = "Hacer Rollback"
    Button.TextColor3 = Color3.fromRGB(255, 255, 255)
    Button.TextSize = 15
    Button.Font = Enum.Font.GothamBold
    Button.Parent = Main

    local BtnCorner = Instance.new("UICorner")
    BtnCorner.CornerRadius = UDim.new(0, 8)
    BtnCorner.Parent = Button

    Button.MouseEnter:Connect(function()
        TweenService:Create(Button, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(0, 140, 220)}):Play()
    end)
    Button.MouseLeave:Connect(function()
        TweenService:Create(Button, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(0, 170, 255)}):Play()
    end)

    Button.MouseButton1Click:Connect(function()
        Button.Text = "Procesando..."
        Button.BackgroundColor3 = Color3.fromRGB(80, 80, 90)
        doDataRollback()
        task.wait(1.2)
        Button.Text = "Hacer Rollback"
        Button.BackgroundColor3 = Color3.fromRGB(0, 170, 255)
    end)

    local Close = Instance.new("TextButton")
    Close.Size = UDim2.new(0, 28, 0, 28)
    Close.Position = UDim2.new(1, -32, 0, 4)
    Close.BackgroundTransparency = 1
    Close.Text = "x"
    Close.TextColor3 = Color3.fromRGB(200, 200, 200)
    Close.TextSize = 22
    Close.Font = Enum.Font.GothamBold
    Close.Parent = Main

    Close.MouseButton1Click:Connect(function()
        ScreenGui:Destroy()
    end)

    notify("AGX HUB desbloqueado", 2.5)
end

