    Title.Size = UDim2.new(1, 0, 0, 36)
    Title.BackgroundTransparency = 1
    Title.Text = "AGX HUB Key System"
    Title.TextColor3 = Color3.fromRGB(255, 255, 255)
    Title.TextSize = 16
    Title.Font = Enum.Font.GothamBold
    Title.Parent = Main

    local KeyBox = Instance.new("TextBox")
    KeyBox.Size = UDim2.new(1, -24, 0, 36)
    KeyBox.Position = UDim2.new(0, 12, 0, 48)
    KeyBox.BackgroundColor3 = Color3.fromRGB(35, 35, 42)
    KeyBox.Text = ""
    KeyBox.PlaceholderText = "Pega tu key aqui..."
    KeyBox.TextColor3 = Color3.fromRGB(255, 255, 255)
    KeyBox.PlaceholderColor3 = Color3.fromRGB(140, 140, 140)
    KeyBox.TextSize = 14
    KeyBox.Font = Enum.Font.Gotham
    KeyBox.ClearTextOnFocus = false
    KeyBox.Parent = Main

    local BoxCorner = Instance.new("UICorner")
    BoxCorner.CornerRadius = UDim.new(0, 8)
    BoxCorner.Parent = KeyBox

    local Submit = Instance.new("TextButton")
    Submit.Size = UDim2.new(1, -24, 0, 40)
    Submit.Position = UDim2.new(0, 12, 0, 100)
    Submit.BackgroundColor3 = Color3.fromRGB(0, 170, 255)
    Submit.Text = "Verificar Key"
    Submit.TextColor3 = Color3.fromRGB(255, 255, 255)
    Submit.TextSize = 14
    Submit.Font = Enum.Font.GothamBold
    Submit.Parent = Main

    local SCorner = Instance.new("UICorner")
    SCorner.CornerRadius = UDim.new(0, 8)
    SCorner.Parent = Submit

    local Info = Instance.new("TextLabel")
    Info.Size = UDim2.new(1, -20, 0, 20)
    Info.Position = UDim2.new(0, 10, 0, 145)
    Info.BackgroundTransparency = 1
    Info.Text = "1d / 5d / 7d / 30d / lifetime"
    Info.TextColor3 = Color3.fromRGB(140, 140, 140)
    Info.TextSize = 11
    Info.Font = Enum.Font.Gotham
    Info.Parent = Main

    Submit.MouseButton1Click:Connect(function()
        local valid, message = checkKey(KeyBox.Text)

        if valid then
            notify(message, 3)
            ScreenGui:Destroy()
            createMainUI()
        else
            notify(message, 3)
            KeyBox.Text = ""
        end
    end)
end

createKeyUI()
